2	 * Stateful JSON lines parser. Buffers partial lines, emits complete JSON objects.
3	 * Strips ANSI escape sequences before parsing.
4	 */
5	
6	// eslint-disable-next-line no-control-regex
7	const ANSI_RE = /\x1b\[[0-9;]*[a-zA-Z]/g
8	
9	export class JsonLinesParser {
10	  private buffer = ''
11	
12	  /**
13	   * Feed a chunk of data. Returns all complete JSON objects parsed from it.
14	   * Partial lines are buffered for the next call.
15	   */
16	  feed(chunk: string): unknown[] {
17	    this.buffer += chunk
18	    const results: unknown[] = []
19	    const lines = this.buffer.split('\n')
20	
21	    // Last element is either empty (line ended with \n) or a partial line
22	    this.buffer = lines.pop()!
23	
24	    for (const line of lines) {
25	      const cleaned = line.replace(ANSI_RE, '').trim()
26	      if (cleaned === '') continue
27	      try {
28	        results.push(JSON.parse(cleaned))
29	      } catch {
30	        // Malformed JSON — skip this line silently
31	        // In production, the SessionManager logger would capture this
32	      }
33	    }
34	
35	    return results
36	  }
37	
38	  /**
39	   * Flush any remaining buffered content. Call when the stream ends.
40	   */
41	  flush(): unknown[] {
42	    if (this.buffer.trim() === '') {
43	      this.buffer = ''
44	      return []
45	    }
46	    const cleaned = this.buffer.replace(ANSI_RE, '').trim()
47	    this.buffer = ''
48	    if (cleaned === '') return []
49	    try {
50	      return [JSON.parse(cleaned)]
51	    } catch {
52	      return []
53	    }
54	  }
55	}
