2	 * SSE parser vendored from @microsoft/fetch-event-source.
3	 * ~160 lines, zero-copy, WHATWG-compliant.
4	 *
5	 * Original: https://github.com/Azure/fetch-event-source
6	 * License: MIT
7	 *
8	 * Three-layer pipeline:
9	 *   getBytes(stream) → getLines(onLine) → getMessages(onId, onRetry, onMessage)
10	 */
11	
12	export interface EventSourceMessage {
13	  id: string
14	  event: string
15	  data: string
16	  retry?: number
17	}
18	
19	/**
20	 * Converts a ReadableStream into a callback pattern.
21	 */
22	export async function getBytes(
23	  stream: ReadableStream<Uint8Array>,
24	  onChunk: (arr: Uint8Array) => void,
25	): Promise<void> {
26	  const reader = stream.getReader()
27	  while (true) {
28	    const result = await reader.read()
29	    if (result.done) break
30	    onChunk(result.value)
31	  }
32	}
33	
34	const enum ControlChars {
35	  NewLine = 10,
36	  CarriageReturn = 13,
37	  Space = 32,
38	  Colon = 58,
39	}
40	
41	/**
42	 * Parses arbitrary byte chunks into EventSource line buffers.
43	 */
44	export function getLines(
45	  onLine: (line: Uint8Array, fieldLength: number) => void,
46	): (arr: Uint8Array) => void {
47	  let buffer: Uint8Array | undefined
48	  let position: number
49	  let fieldLength: number
50	  let discardTrailingNewline = false
51	
52	  return function onChunk(arr: Uint8Array) {
53	    if (buffer === undefined) {
54	      buffer = arr
55	      position = 0
56	      fieldLength = -1
57	    } else {
58	      buffer = concat(buffer, arr)
59	    }
60	
61	    const bufLength = buffer.length
62	    let lineStart = 0
63	
64	    while (position < bufLength) {
65	      if (discardTrailingNewline) {
66	        if (buffer[position] === ControlChars.NewLine) {
67	          lineStart = ++position
68	        }
69	        discardTrailingNewline = false
70	      }
71	
72	      let lineEnd = -1
73	      for (; position < bufLength && lineEnd === -1; ++position) {
74	        switch (buffer[position]) {
75	          case ControlChars.Colon:
76	            if (fieldLength === -1) {
77	              fieldLength = position - lineStart
78	            }
79	            break
80	          case ControlChars.CarriageReturn:
81	            discardTrailingNewline = true
82	          // falls through
83	          case ControlChars.NewLine:
84	            lineEnd = position
85	            break
86	        }
87	      }
88	
89	      if (lineEnd === -1) {
90	        break
91	      }
92	
93	      onLine(buffer.subarray(lineStart, lineEnd), fieldLength)
94	      lineStart = position
95	      fieldLength = -1
96	    }
97	
98	    if (lineStart === bufLength) {
99	      buffer = undefined
100	    } else if (lineStart !== 0) {
101	      buffer = buffer.subarray(lineStart)
102	      position -= lineStart
103	    }
104	  }
105	}
