107	/**
108	 * Parses line buffers into EventSourceMessages.
109	 */
110	export function getMessages(
111	  onId: (id: string) => void,
112	  onRetry: (retry: number) => void,
113	  onMessage?: (msg: EventSourceMessage) => void,
114	): (line: Uint8Array, fieldLength: number) => void {
115	  let message = newMessage()
116	  const decoder = new TextDecoder()
117	
118	  return function onLine(line: Uint8Array, fieldLength: number) {
119	    if (line.length === 0) {
120	      onMessage?.(message)
121	      message = newMessage()
122	    } else if (fieldLength > 0) {
123	      const field = decoder.decode(line.subarray(0, fieldLength))
124	      const valueOffset =
125	        fieldLength + (line[fieldLength + 1] === ControlChars.Space ? 2 : 1)
126	      const value = decoder.decode(line.subarray(valueOffset))
127	
128	      switch (field) {
129	        case 'data':
130	          message.data = message.data ? message.data + '\n' + value : value
131	          break
132	        case 'event':
133	          message.event = value
134	          break
135	        case 'id':
136	          onId((message.id = value))
137	          break
138	        case 'retry': {
139	          const retry = parseInt(value, 10)
140	          if (!isNaN(retry)) {
141	            onRetry((message.retry = retry))
142	          }
143	          break
144	        }
145	      }
146	    }
147	  }
148	}
